#!/usr/bin/env python3
"""Build the five service landing pages that complement existing expertise pages."""
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
BASE = (ROOT / "expertises/seo/index.html").read_text()

def between(text, start, end):
    return text.split(start, 1)[1].split(end, 1)[0]

head_assets = between(BASE, '<meta property="og:type" content="website">', '</head>')
head_assets = re.sub(r'<link rel="canonical"[^>]+>', '', head_assets)
header = between(BASE, '<body class="inner expertise-page">', '<main id="contenu">')
tail = BASE.split('<section class="blog-teaser"', 1)[1]
tail = '<section class="blog-teaser"' + tail

PAGES = [
  dict(path="agence-ia/index.html", slug="agence-ia", title="Agence IA et solutions sur mesure | Ecospheare", h1="Agence IA : des solutions utiles à votre entreprise", desc="Agence IA, Ecospheare conçoit et intègre des solutions d’intelligence artificielle sur mesure, de l’IA générative aux outils métier.", accent="L’intelligence artificielle au service d’un usage concret.", intro="Ecospheare accompagne les entreprises qui veulent transformer une possibilité technique en outil réellement utilisable. Notre agence intelligence artificielle étudie vos données, vos processus et vos contraintes avant de concevoir une solution IA sur mesure.", context="Une agence intelligence artificielle qui part de vos usages", contextp="Un projet pertinent commence par une tâche précise : retrouver une information, assister la rédaction, analyser des documents ou guider une équipe. Nous vérifions les sources disponibles, le niveau de confidentialité attendu et la place de la validation humaine. Cette approche évite d’ajouter de l’IA là où une règle simple serait plus fiable.", cards=[("Cadrage et faisabilité","Nous identifions le problème, les utilisateurs et les critères de réussite. Le cadrage précise aussi les limites, les données accessibles et les situations qui doivent rester sous contrôle humain."),("IA générative et interfaces","Nous pouvons concevoir une interface fondée sur des modèles de langage pour rechercher, synthétiser ou produire un premier brouillon. Les réponses sont encadrées par des consignes, des sources et des droits d’accès."),("Intégration IA en entreprise","La solution peut se connecter à vos outils lorsque leurs API le permettent. Nous prévoyons les erreurs, les journaux utiles et une solution de repli pour conserver un fonctionnement compréhensible.")], detailh="Du prototype au développement d’une solution IA", detailp="Une démonstration convaincante ne suffit pas pour un usage quotidien. Nous testons la qualité des entrées, la régularité des résultats, les coûts d’utilisation et les règles de sécurité avant d’élargir le périmètre. Le développement de solution IA avance par étapes mesurables. Selon le besoin, le projet peut employer ChatGPT, Claude ou un autre modèle adapté, sans dépendre d’une seule interface grand public.", process="Concevoir, tester puis intégrer l’intelligence artificielle", steps=[("Définir le cas d’usage","Nous décrivons les décisions attendues, les personnes concernées et les informations disponibles. Une référence humaine permet de comparer les résultats et de repérer les cas où l’outil doit demander de l’aide."),("Construire un prototype contrôlé","Le prototype teste le parcours principal avec un jeu de données limité. Nous observons la pertinence, les erreurs et le temps gagné avant de décider si un développement plus complet est justifié."),("Déployer avec des garde-fous","Les accès, la supervision, la documentation et le suivi des coûts accompagnent la mise en service. Les règles évoluent avec les retours des utilisateurs et les changements des modèles.")], faq=[("Que fait une agence IA ?","Une agence IA relie un besoin métier à une solution technique exploitable. Elle analyse le processus, choisit l’approche adaptée, développe l’interface et organise l’intégration. Son rôle inclut aussi les tests, la sécurité, la documentation et la place de la validation humaine."),("Quelle différence entre IA générative et automatisation ?","L’IA générative produit ou interprète un contenu avec une part de variabilité. Une automatisation suit un enchaînement défini. Les deux peuvent fonctionner ensemble : l’IA propose une analyse et le workflow applique ensuite une règle validée."),("Pouvez-vous intervenir comme consultant IA entreprise ?","Oui. Une mission peut commencer par un audit et une feuille de route, sans imposer immédiatement un développement. Nous comparons les gains attendus, les risques, les données nécessaires et les solutions déjà disponibles."),("Êtes-vous une agence ChatGPT ou Claude Code ?","Nous pouvons intégrer des modèles et utiliser des outils de développement comme Claude Code lorsque le contexte le justifie. Ecospheare reste indépendante des éditeurs cités et choisit la solution selon le besoin, les accès et les contraintes du projet.")]),
  dict(path="agents-ia.html", slug="agents-ia", title="Agence agent IA sur mesure | Ecospheare", h1="Agence agent IA : créez un assistant sur mesure", desc="Ecospheare conçoit des agents IA sur mesure, assistants intelligents et chatbots IA reliés aux outils et règles de votre entreprise.", accent="Un agent qui sait quand agir et quand vous solliciter.", intro="Un agent IA peut chercher une information, préparer une action ou faire avancer une tâche dans un cadre défini. Ecospheare conçoit des assistants IA sur mesure adaptés à vos outils, à vos règles et au niveau d’autonomie que vous acceptez.", context="Créer un agent IA à partir d’une mission précise", contextp="Nous ne commençons pas par une liste de technologies. Nous décrivons la mission de l’agent, les données qu’il peut consulter, les actions qu’il peut proposer et celles qui exigent une validation. Chaque étape doit rester lisible pour l’équipe qui l’utilise et l’administre.", cards=[("Assistant interne","L’agent peut aider à retrouver une procédure, résumer un dossier ou préparer une réponse à partir de sources autorisées. Les citations et les liens vers les documents facilitent la vérification."),("Agent IA commercial","Un agent IA commercial peut qualifier une demande, préparer un compte rendu ou suggérer une prochaine action. Les décisions sensibles et l’envoi final restent contrôlés selon les règles définies."),("Chatbot IA connecté","Un chatbot IA peut répondre à partir d’un contenu sélectionné et transmettre la conversation lorsqu’il ne dispose pas d’une réponse fiable. Le parcours évite de masquer les limites de l’outil.")], detailh="Un agent IA sur mesure relié au bon contexte", detailp="La qualité dépend autant du contexte que du modèle. Nous organisons les sources, les permissions, la mémoire utile et les outils accessibles. Les scénarios inhabituels, les données sensibles et les erreurs de connexion font partie des tests. L’objectif est de créer un assistant IA sur mesure dont le comportement peut être expliqué, observé et corrigé.", process="De la mission au fonctionnement de l’agent", steps=[("Cartographier les actions","Nous listons les informations à lire, les décisions à préparer et les actions autorisées. Cette cartographie fixe les limites et identifie les validations nécessaires."),("Tester les conversations","Des scénarios réalistes évaluent la compréhension, les réponses, les refus et les transferts vers une personne. Les cas difficiles enrichissent progressivement les règles."),("Suivre et améliorer","La mise en service inclut les journaux utiles, le contrôle des accès et un protocole de correction. Les changements sont évalués avant d’être appliqués à tous les utilisateurs.")], faq=[("Qu’est-ce qu’une agence agent IA ?","Elle conçoit des assistants capables d’utiliser des informations et des outils pour accomplir une mission encadrée. Le travail couvre le parcours, les connexions, les consignes, les autorisations, les tests et le suivi après lancement."),("Un agent IA peut-il remplacer un collaborateur ?","Nous le concevons comme un outil d’assistance sur des tâches identifiées. Les responsabilités, les décisions sensibles et les situations ambiguës restent attribuées à des personnes. Le niveau d’autonomie dépend des risques du processus."),("Comment sécuriser un chatbot IA ?","Nous limitons les sources, les actions et les données accessibles. Les droits sont définis par rôle, les secrets ne sont pas placés dans les consignes et les échanges utiles au diagnostic sont conservés selon une règle explicite."),("Peut-on connecter l’agent au CRM ?","Oui, si le CRM propose une API ou un mécanisme d’intégration adapté. Nous déterminons précisément ce que l’agent peut lire ou préparer et exigeons une validation pour les actions qui engagent l’entreprise.")]),
  dict(path="agence-automatisation/index.html", slug="agence-automatisation", title="Agence automatisation IA et workflows | Ecospheare", h1="Agence automatisation : simplifiez vos processus métier", desc="Agence automatisation, Ecospheare relie vos outils, automatise les processus métier et construit des workflows IA, CRM, API ou n8n.", accent="Moins de doubles saisies, plus de continuité.", intro="Ecospheare conçoit des automatisations qui relient vos outils et réduisent les tâches répétitives. Chaque workflow part d’un processus réel, avec ses exceptions, ses responsables et les contrôles nécessaires.", context="Automatiser les processus sans perdre le contrôle", contextp="Une automatisation utile rend une étape plus fiable ou plus rapide. Nous suivons le chemin de l’information, repérons les ressaisies et choisissons les actions qui peuvent être exécutées sans ambiguïté. Les cas particuliers restent visibles au lieu d’être cachés derrière un scénario fragile.", cards=[("Workflows et n8n","Nous construisons des workflows n8n ou utilisons une autre solution adaptée à votre environnement. Les déclencheurs, conditions, erreurs et reprises sont documentés."),("Intégration API","Une intégration API permet à deux outils d’échanger des données selon des règles précises. Nous contrôlons les formats, les autorisations, les limites et le comportement en cas d’indisponibilité."),("CRM et facturation","La qualification, la création d’une fiche, une relance ou la préparation d’un document peuvent être automatisées. Chaque action financière ou commerciale sensible conserve le niveau de validation prévu.")], detailh="Une agence automatisation IA quand la règle seule ne suffit pas", detailp="L’intelligence artificielle peut classer un message, extraire une information ou préparer un résumé avant qu’un workflow poursuive le traitement. Cette étape reste évaluée différemment d’une règle déterministe. Nous prévoyons un seuil de confiance, une validation ou une file d’exception lorsque l’erreur aurait une conséquence importante.", process="Cartographier, connecter et superviser", steps=[("Observer le processus","Nous suivons plusieurs cas réels pour comprendre les entrées, les décisions, les outils et les personnes responsables. Les exceptions déterminent souvent la solidité du futur workflow."),("Construire par séquences","Chaque connexion est testée séparément avant l’enchaînement complet. Les données de test évitent d’envoyer des messages ou de modifier des dossiers réels pendant la recette."),("Prévoir l’exploitation","Nous ajoutons les alertes, les journaux et la procédure de reprise nécessaires. Votre équipe sait où regarder et quoi faire lorsqu’une étape ne peut pas se terminer.")], faq=[("Quels processus métier peut-on automatiser ?","La collecte de formulaires, la synchronisation CRM, la préparation de documents, certaines relances et la circulation d’informations sont des cas fréquents. Nous retenons surtout les tâches répétitives dont les règles et les exceptions peuvent être décrites."),("Pourquoi travailler avec un expert n8n ?","Un expert n8n ne se limite pas à relier deux blocs. Il organise les autorisations, les erreurs, les doublons, les limites d’API et la maintenance. Le choix de n8n dépend toutefois de votre infrastructure et de vos besoins."),("Peut-on automatiser la facturation ?","Certaines étapes peuvent l’être, comme la préparation de données ou l’envoi après validation. Les règles comptables, les montants et les contrôles doivent être confirmés avec les personnes responsables et les outils concernés."),("Une automatisation IA est-elle toujours préférable ?","Non. Une règle classique est souvent plus prévisible. Nous utilisons l’IA lorsque l’entrée est difficile à traiter avec des conditions simples, par exemple pour classer un texte, tout en prévoyant un contrôle adapté.")]),
  dict(path="agence-developpement-logiciel/index.html", slug="agence-developpement-logiciel", title="Agence développement logiciel sur mesure | Ecospheare", h1="Agence développement logiciel sur mesure", desc="Ecospheare, agence développement logiciel, conçoit des logiciels métier sur mesure, assure leur refonte et organise leur maintenance.", accent="Un logiciel construit autour de votre métier.", intro="Ecospheare conçoit des logiciels sur mesure pour transformer un processus dispersé en outil cohérent. Le produit est cadré avec ses utilisateurs, développé par étapes et documenté pour rester compréhensible dans le temps.", context="Développer un logiciel métier sur mesure", contextp="Nous observons les opérations, les données et les rôles avant de choisir les écrans. Un bon logiciel métier ne reproduit pas toutes les habitudes existantes : il simplifie les étapes utiles, rend les responsabilités visibles et limite les actions qui créent des erreurs.", cards=[("Architecture produit","Le périmètre, les données, les accès et les dépendances sont précisés avant le développement. Les choix techniques tiennent compte de l’usage, de la maintenance et de l’environnement existant."),("Développement progressif","Les fonctions prioritaires sont livrées dans un ordre qui permet de tester rapidement les parcours. Chaque version est relue avec des scénarios concrets avant l’ajout de nouveaux modules."),("Refonte et maintenance","Une refonte logiciel commence par l’inventaire des usages et des données à préserver. La maintenance corrige les anomalies et prépare les évolutions sans confondre les deux types d’intervention.")], detailh="Une entreprise de développement logiciel responsable de la suite", detailp="La livraison comprend plus que du code. Nous définissons les environnements, les accès, la sauvegarde, les tests et le suivi des incidents selon le périmètre. Les décisions structurantes sont documentées. Vous connaissez les dépendances du produit et les conditions nécessaires pour le faire évoluer.", process="Du processus métier au logiciel exploitable", steps=[("Prioriser les usages","Les entretiens et exemples réels permettent d’identifier les tâches principales. Nous distinguons le besoin indispensable, l’amélioration utile et l’idée à vérifier plus tard."),("Concevoir et développer","Les parcours, les règles et les états sont validés avant ou pendant des cycles courts. Les démonstrations régulières rendent les arbitrages visibles et évitent une découverte tardive du produit."),("Recetter et maintenir","La recette couvre les droits, les données, les erreurs et les formats d’écran nécessaires. Après la mise en service, les modalités de support et de maintenance sont définies clairement.")], faq=[("Pourquoi choisir un logiciel sur mesure ?","Le sur mesure devient pertinent lorsqu’un processus important ne peut pas être correctement couvert par un outil existant ou lorsque les adaptations accumulées créent trop de friction. Une étude initiale compare toujours ces options."),("Quelle différence entre logiciel métier et SaaS ?","Un logiciel métier répond à un fonctionnement précis, souvent interne. Un SaaS est généralement proposé à plusieurs clients sous forme d’abonnement. Un produit peut appartenir aux deux catégories selon son usage et son modèle."),("Pouvez-vous reprendre un logiciel existant ?","Oui après un audit du code, de l’hébergement, des données et de la documentation disponibles. Cet examen permet d’estimer s’il vaut mieux corriger, refondre certaines parties ou préparer une migration."),("Comment organiser la maintenance d’un logiciel sur mesure ?","Nous distinguons les anomalies, les mises à jour de sécurité et les nouvelles fonctionnalités. Les priorités, délais d’intervention et responsabilités sont définis dans le cadre de maintenance retenu.")]),
  dict(path="agence-application-mobile/index.html", slug="agence-application-mobile", title="Agence application mobile sur mesure | Ecospheare", h1="Agence application mobile : concevez un outil utile", desc="Ecospheare accompagne la création et le développement d’application mobile ou métier sur mesure, du cadrage à la mise en service.", accent="Une application pensée pour le terrain.", intro="Ecospheare conçoit des applications mobiles adaptées à un parcours précis : service client, opération terrain, espace membre ou outil métier. Le choix d’une application native, hybride ou web dépend des usages attendus.", context="Créer une application mobile autour du bon parcours", contextp="Le téléphone impose des décisions nettes : peu d’espace, des connexions variables et des interactions rapides. Nous concentrons l’interface sur les actions essentielles, puis vérifions si des fonctions comme la caméra, les notifications ou le mode hors ligne sont réellement nécessaires.", cards=[("Expérience mobile","La navigation, les formulaires et les retours d’état sont conçus pour le tactile. L’accessibilité, la lisibilité et les erreurs de saisie sont étudiées dès les premiers écrans."),("Application métier","Une application métier sur mesure peut guider une intervention, consulter un dossier ou collecter des informations sur le terrain. Les synchronisations et droits d’accès sont prévus avec le système central."),("Développement et publication","Nous organisons les environnements, les tests sur appareils et la préparation des éléments nécessaires aux boutiques lorsque le projet en a besoin. Les règles des plateformes restent à prendre en compte.")], detailh="Application mobile, web app ou portail client ?", detailp="Une application à installer n’est pas toujours indispensable. Une application web responsive peut suffire si l’usage passe principalement par un navigateur. Nous comparons l’accès hors ligne, les fonctions du téléphone, la fréquence d’utilisation, la distribution et le budget avant de recommander une architecture.", process="Du scénario mobile à la mise en service", steps=[("Tester le parcours","Un prototype permet de vérifier la compréhension des écrans et la longueur des actions principales. Les utilisateurs concernés peuvent signaler les contraintes du terrain avant le développement complet."),("Développer les fonctions prioritaires","Les connexions, les données et les fonctions du téléphone sont intégrées progressivement. Les versions intermédiaires servent à tester les appareils, les permissions et les cas de réseau dégradé."),("Préparer le lancement","La recette, la politique de confidentialité, les visuels et les comptes de publication sont anticipés. Le suivi des anomalies et des futures versions est défini avant l’ouverture aux utilisateurs.")], faq=[("Combien coûte la création d’une application mobile ?","Le coût dépend du nombre de parcours, des connexions, des rôles, du mode hors ligne et des plateformes visées. Un cadrage permet de proposer un périmètre et des étapes plutôt qu’un montant générique peu fiable."),("Faut-il développer pour iOS et Android ?","Cela dépend de vos utilisateurs et des fonctions nécessaires. Une technologie partagée peut réduire certains efforts, mais le choix doit considérer les performances, les fonctions natives et la maintenance attendue."),("Pouvez-vous créer une application métier sur mesure ?","Oui. Nous partons du processus, des personnes sur le terrain et des données à synchroniser. Les droits, la traçabilité et le fonctionnement avec une connexion instable sont alors particulièrement importants."),("Une application web peut-elle remplacer une application mobile ?","Souvent, lorsque l’installation, les notifications poussées ou certaines fonctions matérielles ne sont pas indispensables. Nous comparons les usages avant de décider, afin de ne pas imposer une complexité inutile.")]),
]

BLOG_AND_FOOTER = tail

def render(p):
    canonical = f"https://ecospheare.com/{p['slug']}/" if p['path'].endswith('/index.html') else f"https://ecospheare.com/{p['path']}"
    cards = ''.join(f'<article><span class="expert-number">0{i}</span><h2>{h}</h2><p>{txt}</p></article>' for i,(h,txt) in enumerate(p['cards'],1))
    steps = ''.join(f'<article><span>0{i}</span><h3>{h}</h3><p>{txt}</p></article>' for i,(h,txt) in enumerate(p['steps'],1))
    faq = ''.join(f'<article><h3>{h}</h3><p>{txt}</p></article>' for h,txt in p['faq'])
    faq_intro = "Ces réponses donnent un premier cadre, mais le choix d’une solution dépend toujours de vos usages, des outils déjà en place et des données disponibles. Pendant le cadrage, nous précisons le périmètre, les responsabilités, les accès et les critères de validation. Nous distinguons aussi ce qui peut être livré dès la première version de ce qui mérite une étape ultérieure. Cette méthode permet d’établir une proposition compréhensible, sans annoncer un délai, un budget ou un résultat avant d’avoir étudié les contraintes réelles du projet. Chaque réponse est ensuite affinée avec les personnes qui utiliseront et administreront la solution."
    page_tail = BLOG_AND_FOOTER.replace('href="/contact/?besoin=seo"', f'href="/contact/?besoin={p["slug"]}"')
    html = f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#ffffff"><title>{p['title']}</title><meta name="description" content="{p['desc']}"><meta property="og:title" content="{p['title']}"><meta property="og:description" content="{p['desc']}"><meta property="og:type" content="website">{head_assets}<link rel="canonical" href="{canonical}"></head><body class="inner expertise-page">{header}<main id="contenu"><section class="expert-hero"><div><nav class="breadcrumb" aria-label="Fil d’Ariane"><a href="/expertises/">Expertises</a><span>/ {p['h1']}</span></nav><h1>{p['h1']}</h1><p class="expert-accent">{p['accent']}</p><p>{p['intro']}</p><a class="button" href="/contact/?besoin={p['slug']}">Parlons de votre projet ↗</a></div></section><section class="expert-context"><p class="eyebrow">Votre besoin, notre point de départ</p><h2>{p['context']}</h2><p>{p['contextp']}</p></section><section class="expert-cards" aria-label="Notre intervention">{cards}</section><section class="expert-detail"><h2>{p['detailh']}</h2><p>{p['detailp']}</p></section><section class="expert-working"><p class="eyebrow">Une collaboration lisible</p><h2>Un périmètre clair.<br><em>Des décisions partagées.</em></h2><div><p>Le premier échange sert à comprendre votre activité, vos contraintes et les outils déjà en place. Nous identifions les informations disponibles, les responsables et les points à préciser avant de proposer une intervention.</p><p>La proposition précise les livrables, les étapes de validation, les responsabilités et les conditions de suivi. Les accès nécessaires sont limités à la mission et les choix sont expliqués pour vous permettre de décider.</p></div></section><section class="expert-process"><p class="eyebrow">Le déroulement de votre projet</p><h2>{p['process']}</h2><div>{steps}</div></section><section class="service-faq" aria-labelledby="faq-{p['slug']}"><p class="eyebrow">Questions fréquentes</p><h2 id="faq-{p['slug']}">Comprendre notre accompagnement</h2><p class="service-faq__intro">{faq_intro}</p><div>{faq}</div></section><nav class="expert-siblings" aria-label="Les autres expertises"><a href="/agence-ia/">Agence IA ↗</a><a href="/agents-ia.html">Agents IA ↗</a><a href="/agence-automatisation/">Automatisation ↗</a><a href="/agence-developpement-logiciel/">Logiciel sur mesure ↗</a><a href="/expertises/web-apps/">Applications web ↗</a><a href="/agence-application-mobile/">Applications mobiles ↗</a><a href="/expertises/saas/">SaaS et MVP ↗</a><a href="/expertises/crm/">CRM et ERP ↗</a><a href="/expertises/sites-web/">Sites web ↗</a></nav>{page_tail}'''
    dest = ROOT / p['path']
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(html)
    mirror = ROOT / 'dist' / p['path']
    mirror.parent.mkdir(parents=True, exist_ok=True)
    mirror.write_text(html)

for page in PAGES:
    render(page)

# Reapply the shared interactive diagnostic after regenerating these pages.
exec((ROOT / "scripts/add-service-diagnostic.py").read_text(), {"__file__": str(ROOT / "scripts/add-service-diagnostic.py")})
